//go:build ppc64le

package floats

// VSX Maximum and Minimum kernels (maxmin.go, POWER8 baseline, gated on hasVSX),
// generated by go-asmgen (maxmin_ppc64le_gen.go) into maxmin_ppc64le.s. A kernel
// does the whole blocks of eight elements; the Go code finishes the last seven
// with the scalar rule.
//
//go:noescape
func maximumVSX(dst, a, b *float64, n int)

//go:noescape
func minimumVSX(dst, a, b *float64, n int)

func vmaximum(dst, a, b []float64) {
	n := len(a) &^ 7
	if n == 0 || !hasVSX {
		maximumRef(dst, a, b)
		return
	}
	maximumVSX(&dst[0], &a[0], &b[0], n)
	maximumRef(dst[n:], a[n:], b[n:])
}

func vminimum(dst, a, b []float64) {
	n := len(a) &^ 7
	if n == 0 || !hasVSX {
		minimumRef(dst, a, b)
		return
	}
	minimumVSX(&dst[0], &a[0], &b[0], n)
	minimumRef(dst[n:], a[n:], b[n:])
}
